import fs from "node:fs";
import path from "node:path";

/**
 * The handful of settings a user has to provide: the SEC contact address and
 * the price-provider keys.
 *
 * They live in `.env.local` and nowhere else — never in the database, never in
 * the build. What this module adds is the ability to read them *without a
 * restart*: `process.env` is only a snapshot of what existed when the server
 * started, and a packaged install is configured from the Settings tab rather
 * than by editing a file and restarting.
 *
 * The file therefore wins over `process.env` when it defines a key, because the
 * file is what the Settings tab writes. A value exported in the shell still
 * works — it is the fallback for keys the file leaves empty or absent.
 */

export const SECRET_KEYS = [
  "SEC_USER_AGENT",
  "TIINGO_API_KEY",
  "ALPHAVANTAGE_API_KEY",
  "CLAUDE_BIN",
] as const;

export type SecretKey = (typeof SECRET_KEYS)[number];

/**
 * Where the install lives.
 *
 * A packaged copy runs Next's standalone server, and that server does
 * `process.chdir(__dirname)` — so `process.cwd()` is the `app/` directory, the
 * one an update overwrites. `STOCKS_HOME` points at the install root instead,
 * where the user's keys and data sit and updates never reach. Unset in
 * development, where the project root is both.
 */
export function stocksHome(): string {
  return (
    process.env.STOCKS_HOME?.trim() ||
    // turbopackIgnore, as elsewhere: the path is built at runtime and the
    // bundler would otherwise try to trace the whole install directory.
    /* turbopackIgnore: true */ process.cwd()
  );
}

/**
 * Is this a copy someone was given, rather than the project it was built from?
 *
 * The launcher of a packaged install sets `STOCKS_HOME`; `next dev` never does.
 * Tools for assembling and updating a package belong to whoever builds the
 * copy — on the receiving end they can only break the install they run from.
 */
export function isPackaged(): boolean {
  return Boolean(process.env.STOCKS_HOME?.trim());
}

export function envFilePath(): string {
  return path.join(stocksHome(), ".env.local");
}

/**
 * Minimal `.env` reader — `KEY=value`, optional quotes, `#` comments.
 *
 * Deliberately not a dependency: the file this parses is one the app itself
 * writes, and the format never grows beyond these four keys.
 */
export function parseEnv(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const eq = line.indexOf("=");
    if (eq < 1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length > 1) ||
      (value.startsWith("'") && value.endsWith("'") && value.length > 1)
    ) {
      value = value.slice(1, -1);
    }
    out[key] = value;
  }
  return out;
}

/** Re-read only when the file actually changed; every SEC call asks for this. */
let cache: { mtimeMs: number; size: number; values: Record<string, string> } | null = null;

function fromFile(): Record<string, string> {
  try {
    const stat = fs.statSync(envFilePath());
    if (cache && cache.mtimeMs === stat.mtimeMs && cache.size === stat.size) return cache.values;
    const values = parseEnv(fs.readFileSync(envFilePath(), "utf8"));
    cache = { mtimeMs: stat.mtimeMs, size: stat.size, values };
    return values;
  } catch {
    cache = null;
    return {};
  }
}

export function getSecret(key: SecretKey): string | undefined {
  const fromEnvFile = fromFile()[key]?.trim();
  if (fromEnvFile) return fromEnvFile;
  const fromProcess = process.env[key]?.trim();
  return fromProcess || undefined;
}

/** Everything the Settings tab shows, already resolved through the same path. */
export function readSecrets(): Record<SecretKey, string> {
  return Object.fromEntries(SECRET_KEYS.map((k) => [k, getSecret(k) ?? ""])) as Record<
    SecretKey,
    string
  >;
}

/**
 * Merge values into `.env.local`, keeping comments and any keys we do not
 * manage. An empty value removes the key rather than writing `KEY=""`, so
 * "cleared in the UI" and "never set" end up as the same state.
 */
export function writeSecrets(patch: Partial<Record<SecretKey, string>>): void {
  const file = envFilePath();
  const existing = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : "";
  const lines = existing ? existing.split(/\r?\n/) : [];

  const managed = new Set<string>(Object.keys(patch));
  const written = new Set<string>();

  const out = lines.filter((raw) => {
    const eq = raw.trim().startsWith("#") ? -1 : raw.indexOf("=");
    if (eq < 1) return true;
    const key = raw.slice(0, eq).trim();
    if (!managed.has(key)) return true;

    const value = patch[key as SecretKey]?.trim();
    if (!value) return false; // cleared — drop the line entirely
    written.add(key);
    return true;
  });

  // Rewrite the lines we kept, then append keys the file did not have yet.
  const rendered = out.map((raw) => {
    const eq = raw.trim().startsWith("#") ? -1 : raw.indexOf("=");
    if (eq < 1) return raw;
    const key = raw.slice(0, eq).trim();
    if (!written.has(key)) return raw;
    return `${key}=${quote(patch[key as SecretKey]!.trim())}`;
  });

  for (const [key, value] of Object.entries(patch)) {
    const trimmed = value?.trim();
    if (!trimmed || written.has(key)) continue;
    rendered.push(`${key}=${quote(trimmed)}`);
  }

  const text = rendered.join("\n").replace(/\n{3,}$/, "\n\n").trimEnd() + "\n";

  // 0600: the file holds API keys and the app may run on a shared machine.
  fs.writeFileSync(file, text, { mode: 0o600 });
  try {
    fs.chmodSync(file, 0o600); // no-op on Windows, matters on re-writes elsewhere
  } catch {
    /* Windows has no POSIX modes; the write above is still correct. */
  }
  cache = null;
}

function quote(value: string): string {
  return /[\s#"'`$]/.test(value) ? `"${value.replace(/"/g, '\\"')}"` : value;
}
