/**
 * What sector a company belongs to when no index list says so.
 *
 * Sector and sub-industry used to live only in the `universe` table, which is
 * filled from the S&P constituent lists. A company outside those lists — a
 * hand-added symbol — therefore had no sector at all: the picker showed a dash,
 * the filter never offered it, and `findPeers()` had nothing to compare it
 * against. The only classification SEC gives us is the SIC code, which every
 * filer has, so that is what fills the gap.
 *
 * SIC is not GICS and the translation below is coarse by nature: SIC was
 * written for a manufacturing economy in the 1930s and asks "what does this
 * company make", while GICS asks "what drives this stock". They disagree at the
 * edges — a company that both writes software and sells hardware lands wherever
 * its filing agent once put it. The mapping is therefore kept at the level of
 * SIC major groups, with exceptions only where a whole group would land in the
 * plainly wrong sector.
 *
 * Because it is an approximation, every stored value records where it came
 * from (`companies.sector_source`), the same way `splits.source` distinguishes
 * a reported split from a derived one. An index list always wins when it has an
 * opinion.
 *
 * How good is it? Measured against the 902 companies whose real GICS sector the
 * S&P lists give us, this mapping agrees with 85.8 % of them. The exceptions
 * below were written by looking at where it disagreed, but only where a whole
 * group was landing in the wrong place — the remaining misses are cases where
 * the two systems genuinely classify differently (plastics makers split between
 * Materials and Industrials, "electronic components" between Industrials and
 * Information Technology) and no table can settle them. Tuning further would
 * just be fitting the S&P sample rather than the question.
 */

/** Where a stored classification came from. */
export type SectorSource = "index" | "sic";

/** The eleven GICS sectors, exactly as the constituent lists spell them. */
export const SECTORS = [
  "Communication Services",
  "Consumer Discretionary",
  "Consumer Staples",
  "Energy",
  "Financials",
  "Health Care",
  "Industrials",
  "Information Technology",
  "Materials",
  "Real Estate",
  "Utilities",
] as const;

export type Sector = (typeof SECTORS)[number];

/**
 * Four-digit codes that would be misfiled by their major group alone.
 *
 * Each one is a case where the group's general answer is wrong for most of the
 * companies in it — drug makers inside the chemicals group, carmakers inside
 * transportation equipment, REITs inside holding offices.
 */
const PRESNE: Array<[RegExp, Sector]> = [
  [/^302\d$/, "Consumer Discretionary"], // gumová a plastová obuv uvnitř plastů
  [/^283\d$/, "Health Care"], // léčiva a biotech uvnitř chemie
  [/^284\d$/, "Consumer Staples"], // mýdla a kosmetika, taktéž uvnitř chemie
  [/^341\d$/, "Materials"], // plechovky a obaly uvnitř kovovýroby
  [/^3533$/, "Energy"], // technika pro ropná pole uvnitř strojírenství
  [/^357\d$/, "Information Technology"], // počítače a periferie
  [/^36[35]\d$/, "Consumer Discretionary"], // spotřebiče a domácí audio/video
  [/^36[678]\d$/, "Information Technology"], // komunikační technika, polovodiče, součástky
  [/^371\d$/, "Consumer Discretionary"], // osobní auta uvnitř dopravní techniky
  [/^375\d$/, "Consumer Discretionary"], // motocykly a jízdní kola
  [/^379\d$/, "Consumer Discretionary"], // obytné vozy, čtyřkolky, lodě
  [/^3812$/, "Industrials"], // navigace a detekce = letectví a obrana
  [/^3823$/, "Industrials"], // průmyslová měřicí technika
  [/^3826$/, "Health Care"], // laboratorní analytika (life sciences tools)
  [/^384\d$/, "Health Care"], // zdravotnické přístroje
  [/^15[23]\d$/, "Consumer Discretionary"], // developeři bydlení uvnitř stavebnictví
  [/^492[23]$/, "Energy"], // přeprava plynu = midstream, ne rozvod koncovým zákazníkům
  [/^632\d$/, "Health Care"], // zdravotní pojišťovny a managed care
  [/^5045$/, "Information Technology"], // velkoobchod s výpočetní technikou
  [/^5065$/, "Information Technology"], // velkoobchod s elektronickými součástkami
  [/^514\d$/, "Consumer Staples"], // velkoobchod s potravinami
  [/^5122$/, "Health Care"], // velkoobchod s léčivy
  [/^533\d$/, "Consumer Staples"], // diskonty a variety stores
  [/^54\d\d$/, "Consumer Staples"], // potraviny v maloobchodu
  [/^5912$/, "Consumer Staples"], // lékárny
  [/^6798$/, "Real Estate"], // REIT uvnitř investičních společností
  [/^7370$/, "Communication Services"], // obecné "data processing" = internetová média
  [/^7373$/, "Industrials"], // systémová integrace bývá spíš služba než software
  [/^731\d$/, "Communication Services"], // reklama
  [/^738\d$/, "Financials"], // "business services, NEC" — nejčastěji platební služby
  [/^751\d$/, "Industrials"], // půjčovny aut = pozemní doprava
  [/^8731$/, "Health Care"], // "commercial physical & biological research" = biotech
];

/**
 * SIC major groups (the first two digits) and where they land.
 *
 * Ranges rather than a list of every code: SIC has about 1 000 of them and the
 * group is what carries the meaning. Where a whole group would be misfiled,
 * the exception lives in PRESNE above.
 */
const SKUPINY: Array<[number, number, Sector]> = [
  [1, 9, "Consumer Staples"], // zemědělství, lesnictví, rybolov
  [10, 10, "Materials"], // těžba rud
  [12, 12, "Energy"], // uhlí
  [13, 13, "Energy"], // ropa a plyn
  [14, 14, "Materials"], // nerudné suroviny
  [15, 17, "Industrials"], // stavebnictví (developeři bydlení viz PRESNE)
  [20, 21, "Consumer Staples"], // potraviny, tabák
  [22, 23, "Consumer Discretionary"], // textil, oděvy
  [24, 24, "Materials"], // dřevo
  [25, 25, "Consumer Discretionary"], // nábytek
  [26, 26, "Materials"], // papír
  [27, 27, "Communication Services"], // tisk a vydavatelství
  [28, 28, "Materials"], // chemie (léčiva a kosmetika viz PRESNE)
  [29, 29, "Energy"], // rafinerie
  [30, 30, "Materials"], // guma a plasty
  [31, 31, "Consumer Discretionary"], // kůže
  [32, 33, "Materials"], // sklo, kámen, hutnictví
  [34, 35, "Industrials"], // kovovýroba a strojírenství (počítače viz PRESNE)
  [36, 36, "Industrials"], // elektrotechnika (součástky a polovodiče viz PRESNE)
  [37, 37, "Industrials"], // dopravní technika (auta viz PRESNE)
  [38, 38, "Information Technology"], // měřicí technika (zdravotnická viz PRESNE)
  [39, 39, "Consumer Discretionary"], // ostatní zpracovatelský průmysl
  [40, 47, "Industrials"], // doprava a logistika
  [48, 48, "Communication Services"], // telekomunikace
  [49, 49, "Utilities"], // energetika a vodárny
  [50, 51, "Industrials"], // velkoobchod (léčiva a IT viz PRESNE)
  [52, 59, "Consumer Discretionary"], // maloobchod (potraviny a lékárny viz PRESNE)
  [60, 64, "Financials"], // banky, úvěry, makléři, pojišťovny
  [65, 66, "Real Estate"], // nemovitosti
  [67, 67, "Financials"], // investiční společnosti (REIT viz PRESNE)
  [70, 70, "Consumer Discretionary"], // hotely
  [72, 73, "Information Technology"], // služby podnikům včetně softwaru (reklama viz PRESNE)
  [75, 76, "Consumer Discretionary"], // opravny a servis (půjčovny aut viz PRESNE)
  [78, 78, "Communication Services"], // film
  [79, 79, "Communication Services"], // zábava a rekreace
  [80, 80, "Health Care"], // zdravotní péče
  [82, 82, "Consumer Discretionary"], // vzdělávání
  [83, 83, "Health Care"], // sociální služby
  [87, 87, "Industrials"], // projekce, účetnictví, výzkum (biotech viz PRESNE)
];

/**
 * Sector for a SIC code, or null when there is nothing to go on.
 *
 * Null is a real answer and stays stored as null: ETFs file no SIC at all, and
 * group 99 means "nonclassifiable", which is not the same as a guess.
 */
export function sectorFromSic(sic: string | null | undefined): Sector | null {
  const code = (sic ?? "").trim();
  if (!/^\d{3,4}$/.test(code)) return null;

  const ctyri = code.padStart(4, "0");
  for (const [vzor, sektor] of PRESNE) {
    if (vzor.test(ctyri)) return sektor;
  }

  const skupina = Number(ctyri.slice(0, 2));
  for (const [od, do_, sektor] of SKUPINY) {
    if (skupina >= od && skupina <= do_) return sektor;
  }
  return null;
}
